const DASHBOARD_CSS: &str = r#":root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f6f7f9;
  color: #1f2933;
}

body {
  margin: 0;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

.topbar {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: center;
  padding: 24px 32px;
  background: #111827;
  color: #ffffff;
}

.topbar h1 {
  margin: 0 0 6px;
  font-size: 28px;
  letter-spacing: 0;
}

.topbar p {
  margin: 0;
  color: #cbd5e1;
}

button {
  border: 1px solid #94a3b8;
  background: #ffffff;
  color: #111827;
  border-radius: 6px;
  padding: 8px 12px;
  font-weight: 600;
  cursor: pointer;
}

main {
  width: min(1180px, calc(100vw - 32px));
  margin: 24px auto 48px;
}

.band {
  margin: 0 0 28px;
}

.band h2 {
  font-size: 18px;
  margin: 0 0 12px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}

.tile,
.row {
  background: #ffffff;
  border: 1px solid #d8dee6;
  border-radius: 6px;
  padding: 12px;
}

.label {
  color: #64748b;
  font-size: 12px;
  text-transform: uppercase;
}

.value {
  margin-top: 6px;
  font-size: 18px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.panel-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid #edf1f6;
  padding-top: 8px;
  margin-top: 8px;
}

.panel-row span:last-child {
  text-align: right;
  overflow-wrap: anywhere;
}

.table-wrap {
  overflow-x: auto;
  border: 1px solid #d8dee6;
  border-radius: 6px;
  background: #ffffff;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 980px;
}

th,
td {
  padding: 10px 12px;
  border-bottom: 1px solid #e5eaf0;
  text-align: left;
  vertical-align: top;
}

th {
  background: #eef2f6;
  color: #334155;
  font-size: 12px;
  text-transform: uppercase;
}

td {
  font-size: 13px;
}

.path {
  max-width: 260px;
  overflow-wrap: anywhere;
}

.muted {
  color: #64748b;
}

.list {
  display: grid;
  gap: 8px;
}

.row {
  display: grid;
  gap: 4px;
}

.workbench-shell {
  display: grid;
  gap: 12px;
}

.workbench-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.workbench-tab {
  background: #ffffff;
  border: 1px solid #d8dee6;
  border-radius: 6px;
  color: #334155;
  font-weight: 700;
  padding: 8px 10px;
}

.workbench-tab[aria-selected="true"] {
  background: #111827;
  color: #ffffff;
}

.workbench-panels,
.workbench-boundary {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.workbench-panel,
.workbench-drawer {
  background: #ffffff;
  border: 1px solid #d8dee6;
  border-radius: 6px;
  padding: 12px;
}

.workbench-panel h3,
.workbench-drawer summary {
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 8px;
}

.status-healthy {
  color: #166534;
}

.status-error,
.status-stale {
  color: #991b1b;
}

.status-degraded,
.status-unknown {
  color: #92400e;
}

@media (max-width: 720px) {
  main {
    width: min(100%, calc(100vw - 24px));
    margin-top: 18px;
  }

  .topbar {
    align-items: flex-start;
    flex-direction: column;
    padding: 20px 16px;
  }

  .topbar h1 {
    font-size: 24px;
  }

  .topbar button,
  td button {
    max-width: 100%;
    white-space: normal;
  }

  .table-wrap {
    overflow-x: visible;
  }

  table,
  tbody,
  tr,
  td {
    display: block;
    min-width: 0;
    width: 100%;
  }

  table {
    min-width: 0;
  }

  thead {
    display: none;
  }

  tr {
    border-bottom: 1px solid #e5eaf0;
    padding: 8px 0;
  }

  tr:last-child {
    border-bottom: 0;
  }

  td {
    display: grid;
    grid-template-columns: 116px minmax(0, 1fr);
    gap: 10px;
    border-bottom: 0;
    padding: 6px 12px;
  }

  td::before {
    content: attr(data-label);
    color: #475569;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
  }

  .path {
    max-width: none;
  }
}
"#;

