        assert!(DASHBOARD_HTML.contains("production-order-lifecycle-audit"));
        assert!(DASHBOARD_HTML.contains("v0.20 订单生命周期审计只读视图"));
        let renderer = dashboard_js_function_body("renderProductionOrderLifecycleAudit");
